  const assert = require('node:assert')
  const fastify = Fastify()
  fastify.get('/', {
    schema: {
      querystring: {
        type: 'object',
        properties: {
          param: { type: ['integer', 'null'] }
        }
      }
    }
  }, async (req, reply) => {
    return { param: req.query.param }
  })

  const res = await fastify.inject({
    method: 'GET',
    url: '/?param='
  })
  assert.strictEqual(JSON.parse(res.payload).param, null)
})

