'use strict'

// Ajv coerces the data inside every `anyOf`/`oneOf` branch, writing the
// coerced value back to the parent object. A schema such as
// `anyOf: [{ type: 'null' }, { type: 'number' }]` therefore turns `0` into
// `null`, because the `null` branch is evaluated first and `0` is coercible
// to `null`.
// Merging the branches that only declare a type into a single union type
// (`{ type: ['null', 'number'] }`) is semantically equivalent and lets Ajv
// skip the coercion whenever the value already matches one of the types,
// while still coercing the values that need it (eg. `''` in a querystring).

const SCHEMA_KEYWORDS = [
  'items', 'prefixItems', 'additionalItems', 'unevaluatedItems',
  'additionalProperties', 'unevaluatedProperties', 'propertyNames',
  'contains', 'not', 'if', 'then', 'else',
  'allOf', 'anyOf', 'oneOf'
]

const SCHEMA_MAP_KEYWORDS = [
  'properties', 'patternProperties', 'definitions', '$defs', 'dependentSchemas'
]

function isTypeOnlySchema (branch) {
  if (branch === null || typeof branch !== 'object' || Array.isArray(branch)) {
    return false
  }
  const keys = Object.keys(branch)
  if (keys.length !== 1 || keys[0] !== 'type') {
    return false
  }
  const { type } = branch
  return typeof type === 'string' ||
    (Array.isArray(type) && type.every(t => typeof t === 'string'))
}

/**
 * Merges the branches that only declare a type into a single branch
 * declaring the union of those types.
 * @param {Array} branches the `anyOf`/`oneOf` branches
 * @param {string} keyword `anyOf` or `oneOf`
 * @returns {Array} the branches, unchanged when there is nothing to merge
 */
function mergeTypeOnlyBranches (branches, keyword) {
  if (!Array.isArray(branches)) {
    return branches
  }

  const types = []
  let count = 0
  for (const branch of branches) {
    if (!isTypeOnlySchema(branch)) continue
    count++
    for (const type of [].concat(branch.type)) {
      if (!types.includes(type)) {
        types.push(type)
      }
    }
  }

  if (count < 2 || types.length < 2) {
    return branches
  }

  // `oneOf` requires exactly one matching branch: merging overlapping types
  // (or duplicated ones) would change the number of matches
  if (keyword === 'oneOf' &&
    (types.includes('integer') === types.includes('number') || types.length !== count)) {
    return branches
  }

  const merged = [{ type: types }]
  for (const branch of branches) {
    if (!isTypeOnlySchema(branch)) {
      merged.push(branch)
    }
  }
  return merged
}

