 * (and of all its subschemas) to avoid unwanted Ajv type coercions.
 * @param {object} schema a JSON schema
 * @returns {object} the rewritten schema, or the same schema when there is
 * nothing to rewrite
 */
function normalizeSchemaTypeUnions (schema) {
  if (Array.isArray(schema)) {
    let changed = false
    const items = schema.map(item => {
      const normalized = normalizeSchemaTypeUnions(item)
      changed = changed || normalized !== item
      return normalized
    })
    return changed ? items : schema
  }

  if (schema === null || typeof schema !== 'object') {
    return schema
