      const normalized = normalizeSchemaTypeUnions(subSchemas[key])
      if (normalized === subSchemas[key]) continue
      if (subResult === subSchemas) subResult = Object.assign({}, subSchemas)
      subResult[key] = normalized
    }
    if (subResult === subSchemas) continue
    if (result === schema) result = Object.assign({}, schema)
    result[keyword] = subResult
  }

  for (const keyword of SCHEMA_KEYWORDS) {
    if (!Object.hasOwn(schema, keyword)) continue
    let normalized = normalizeSchemaTypeUnions(schema[keyword])
